public class PieWedgePainterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String pixel(java.awt.image.BufferedImage img, int x, int y) {
        if (img == null) {
            return "null-image";
        }
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    static java.awt.image.BufferedImage render(int[] values, int size, java.awt.Color[] colors) {
        java.awt.image.BufferedImage img = new java.awt.image.BufferedImage(
                size, size, java.awt.image.BufferedImage.TYPE_INT_RGB);
        java.awt.Graphics2D g = img.createGraphics();
        try {
            PieWedgePainter.paint(g, values, size, colors);
        } finally {
            g.dispose();
        }
        return img;
    }

    public static void main(String[] args) {
        try {
            java.awt.Color[] four = { java.awt.Color.RED, java.awt.Color.GREEN, java.awt.Color.BLUE, java.awt.Color.YELLOW };
            java.awt.image.BufferedImage a = render(new int[] { 1, 1, 1, 1 }, 80, four);
            java.awt.image.BufferedImage b = render(new int[] { 3, 1 }, 80, four);
            check("first wedge is top-right (60,20)", "#FF0000", pixel(a, 60, 20));
            check("second wedge is bottom-right (60,60)", "#00FF00", pixel(a, 60, 60));
            check("third wedge is bottom-left (20,60)", "#0000FF", pixel(a, 20, 60));
            check("fourth wedge is top-left (20,20)", "#FFFF00", pixel(a, 20, 20));
            check("corner outside the circle (4,4)", "#FFFFFF", pixel(a, 4, 4));
            check("three-quarter wedge top-right (60,20)", "#FF0000", pixel(b, 60, 20));
            check("three-quarter wedge bottom-left (20,60)", "#FF0000", pixel(b, 20, 60));
            check("remaining quarter top-left (20,20)", "#00FF00", pixel(b, 20, 20));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

