import java.awt.Color;
import java.awt.Graphics2D;

public class PieWedgePainter {

    public static void paint(Graphics2D g, int[] values, int size, Color[] colors) {
        g.setColor(Color.WHITE);
        g.fillRect(0, 0, size, size);

        int total = 0;
        for (int v : values) {
            total += v;
        }
        if (total <= 0) {
            return;
        }

        int start = 90;
        for (int i = 0; i < values.length; i++) {
            int sweep = values[i] * 360 / total;
            g.setColor(colors[i % colors.length]);
            g.fillArc(0, 0, size, size, start, -sweep);
            start = start - sweep;
        }
    }
}
